import{_ as t,o as r,c as n,ak as o}from"./chunks/framework.B8jO0odJ.js";const u=JSON.parse('{"title":"Chainy product acceptance checklist","description":"Updated November 11, 2026 for the lesson-collection GDD.\\nThis document defines planned acceptance; it does not report an implemented or tested build.\\nCurrent authorization is ","frontmatter":{"title":"Chainy product acceptance checklist","description":"Updated November 11, 2026 for the lesson-collection GDD.\\nThis document defines planned acceptance; it does not report an implemented or tested build.\\nCurrent authorization is ","source":"docs/archive/pre-lesson-collection-2026-11-11/requirements/product-requirements.md","category":"Archive","sourceUpdated":"2026-11-11T12:24:37+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/archive/pre-lesson-collection-2026-11-11/requirements/product-requirements.md","filePath":"content/docs/archive/pre-lesson-collection-2026-11-11/requirements/product-requirements.md"}'),a={name:"content/docs/archive/pre-lesson-collection-2026-11-11/requirements/product-requirements.md"};function i(s,e,c,d,l,p){return r(),n("div",null,[...e[0]||(e[0]=[o('<div><h1 id="chainy-product-acceptance-checklist">Chainy product acceptance checklist<a class="header-anchor" href="#chainy-product-acceptance-checklist" aria-label="Link to this section">​</a></h1><p>Updated November 11, 2026 for the <a href="/Chainy-Docs/content/docs/game-design-lesson-collection.html">lesson-collection GDD</a>. This document defines planned acceptance; it does not report an implemented or tested build. <strong>Current authorization is documentation and setup only; final owner approval is required before Unity development.</strong> The <a href="/Chainy-Docs/content/docs/project-baseline.html">baseline</a> records decisions and the <a href="/Chainy-Docs/content/docs/planning/lesson-collection-delivery.html">execution plan</a> records the approval boundary.</p><h2 id="current-acceptance-map">Current acceptance map<a class="header-anchor" href="#current-acceptance-map" aria-label="Link to this section">​</a></h2><p>Use the <a href="/Chainy-Docs/content/docs/game-design-lesson-collection.html#12-design-acceptance-cases">GDD&#39;s LC-G acceptance cases</a> as the single detailed gameplay checklist. The map below identifies evidence needed later without duplicating its lesson route or minigame rules.</p><table><thead><tr><th>Area</th><th>Intended outcome</th><th>Later evidence</th></tr></thead><tbody><tr><td>World access and orientation</td><td>Main menu opens world selection; Web3, Blockchain, and AI unlock sequentially; each island has a remembered first-visit tutorial</td><td>New-profile, returning-profile, and locked-world checks</td></tr><tr><td>Lesson collection</td><td>Each world has 13 ordered source lessons, totaling 39; collecting an entry activates only its next lesson</td><td>Source coverage, out-of-order interaction, and duplicate-record checks</td></tr><tr><td>Minigames</td><td>Exactly three distinct minigames per world, nine total, entered through ordered item/NPC/facility prerequisites in separate scenes</td><td>Each activity&#39;s success, wrong action, retry, exit, and return checks</td></tr><tr><td>Encyclopedia and required review</td><td>All 13 entries open the required review; its approved completion rule controls world completion and the next unlock</td><td>Collection/quiz state checks, including abandonment and replay</td></tr><tr><td>Offline progress</td><td>SQLite keeps profile-specific progress consistent across scenes, failed saves, and relaunch</td><td>Named-build recovery and two-synthetic-profile results</td></tr><tr><td>Usability and teaching accuracy</td><td>Touch controls and feedback work on the reference phone; essential information works without sound or color; AI simulations are labeled</td><td>Actual device observations and content review</td></tr><tr><td>Delivery and school evidence</td><td>Honest scope statement, manuscript, approved evidence, and rehearsed recovery for the November 21 pre-final</td><td>Build/device records, limitations, actual school guidance, and demonstration evidence</td></tr></tbody></table><p>World sequencing, 39 lessons, nine minigames, and required quizzes are confirmed design direction. The proposed five-question review with correction retries is <strong>pending the owner&#39;s choice</strong>; neither the question count nor a pass threshold is approved by this checklist. Final quiz acceptance must reference the selected GDD rule before development starts. Completing documentation or setup does not satisfy runtime acceptance.</p><p>The reference device remains Android 10/API 29, 4 GB RAM, 128 GB total storage, and a reported 2.3 GHz octa-core CPU. API 25 is the retained minimum install setting, not proof of compatibility on every device. Keep participant identities, credentials, and signing keys outside project records. The November 10 session is a past scheduled event whose actual outcome must be recorded from evidence. <strong>Pre-final remains November 21, 2026.</strong></p><h2 id="historical-v2-requirements">Historical V2 requirements<a class="header-anchor" href="#historical-v2-requirements" aria-label="Link to this section">​</a></h2><p>The following October 23 definitions preserve the meanings of V2-R01–12 for existing records. They are not the current implementation backlog or an instruction to restore an economy. Their wallet/purchase/ledger progression, four-stage encyclopedia labels, actual-classifier stretch gate, and standalone-game scope were superseded by the lesson-collection direction. Retained Android, privacy, and evidence constraints are restated above and in the <a href="/Chainy-Docs/content/docs/requirements/technical-requirements.html">technical checklist</a>. November 10 dates below describe the historical plan, not present deadlines or evidence of completion.</p><table><thead><tr><th>ID</th><th>Scope</th><th>Required outcome and acceptance evidence</th></tr></thead><tbody><tr><td>V2-R01</td><td>CORE</td><td>A named Android build installs, opens and completes the adopted chapter offline on the confirmed minimum reference phone: Android 10 (API level 29), 4 GB RAM, 128 GB total storage and reported 2.3 GHz octa-core CPU. Record revision, non-sensitive device details and result; higher-spec testing alone does not pass this requirement.</td></tr><tr><td>V2-R02</td><td>CORE</td><td>Explore a compact fixed-camera 3D world, interact, open live-world dialogue and recover from pause/back/load failure. World input is disabled during dialogue.</td></tr><tr><td>V2-R03</td><td>CORE</td><td>W01–W04: select the fictional wallet/address safely, earn 12 once, review a lantern purchase of 8 + 1 fee, confirm balance 3 and unique ownership, equip without another charge, restore the workshop. Cancellation is free; repeated taps cannot duplicate rewards/purchases.</td></tr><tr><td>V2-R04</td><td>CORE</td><td>B01–B03 and demo B07: reuse the same purchase record; connect three blocks to a trusted checkpoint; reject the altered 6 versus original 8 record; restore the beacon. This is not BlockMatch or a real blockchain.</td></tr><tr><td>V2-R05</td><td>CORE</td><td>Quest states, early pickups, objectives, report-back, prerequisites and completion behave consistently. Contextual Quiz feedback explains decisions without substituting recall for gameplay.</td></tr><tr><td>V2-R06</td><td>CORE</td><td>SQLite persists profile, build/content/schema versions, quest and encyclopedia progress, balances, inventory, ledger, restoration and checkpoints; relaunch, repeat save and failed save tests preserve consistency and profile separation. No silent reset.</td></tr><tr><td>V2-R07</td><td>CORE</td><td>Quest log and encyclopedia use Discovered / Explained / Practiced / Demonstrated. Clear touch UI, instructions and save-error recovery work on named devices; these labels do not prove mastery.</td></tr><tr><td>V2-R08</td><td>CORE</td><td>Demonstrate and label the completed demo chapter honestly. Record accepted/missing scope, known issues, safe beta procedure and tested recovery. Community feedback is not automatically school-approved research.</td></tr><tr><td>V2-R09</td><td>STRETCH</td><td>A01–A03: learner labels examples, trains an actual small local classifier, revises after separate practice cases and records a first reserved-final-set test. Do not present authored responses as trained AI. Admit only after core passes.</td></tr><tr><td>V2-R10</td><td>FULL</td><td>Retain W05–W08, B04–B06/full B07, A04–A05, all twelve concepts, and standalone Wordle/BlockMatch with their own approved rules. Not November 10 acceptance blockers.</td></tr><tr><td>V2-R11</td><td>LATER SERVICE</td><td>Personal learner phones; teacher provisioning/vouchers, offline pairing, protected dashboard, collection, upload and distribution require separate design/prototype/security gates. Local demo profiles are not authenticated enrollment.</td></tr><tr><td>V2-R12</td><td>PRE-FINAL</td><td>November 21: tested functional build, honest scope statement, manuscript, actual approved evaluation/pilot-area evidence and rehearsed recovery. Confirm the school&#39;s 60% calculation and criteria; never infer it from task counts.</td></tr></tbody></table><p>Historical <a href="/Chainy-Docs/content/docs/archive/pre-v2-adoption-2026-10-23/docs/requirements/product-requirements.html">TD-R01–10</a> and <a href="/Chainy-Docs/content/docs/archive/pre-2026-10-12/docs/requirements/product-requirements.html">CH-R01–12</a> retain their original meanings. No issue is Done merely because its specification or dates changed.</p></div>',1)])])}const m=t(a,[["render",i]]);export{u as __pageData,m as default};
